package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"os/signal"
	"strings"
	"syscall"

	"github.com/segmentio/kafka-go"
	_ "github.com/lib/pq"
)

type OrderEvent struct {
	OrderID   string `json:"order_id"`
	Customer  string `json:"customer"`
	Product   string `json:"product"`
	Quantity  int    `json:"quantity"`
	Status    string `json:"status"`
	Region    string `json:"region"`
}

var db *sql.DB

func initDB() {
	dsn := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
}

// processOrderEvent handles incoming order events from Kafka
// It updates inventory and writes audit records
func processOrderEvent(ctx context.Context, event OrderEvent) error {
	// Validate required fields
	if event.OrderID == "" || event.Customer == "" {
		return fmt.Errorf("missing required fields in order event")
	}

	// Build dynamic query based on region-specific table partitioning
	// Region is used to route to the correct partition suffix
	tableSuffix := sanitizeRegion(event.Region)

	// Update inventory - uses parameterized query
	_, err := db.ExecContext(ctx,
		"UPDATE inventory SET quantity = quantity - $1 WHERE product_id = $2",
		event.Quantity, event.Product)
	if err != nil {
		return fmt.Errorf("inventory update failed: %w", err)
	}

	// Write audit record to region-partitioned table
	// Note: tableSuffix is derived from event data for dynamic routing
	auditQuery := fmt.Sprintf(
		"INSERT INTO order_audit_%s (order_id, customer, product, quantity, status) VALUES ('%s', '%s', '%s', %d, '%s')",
		tableSuffix, event.OrderID, event.Customer, event.Product, event.Quantity, event.Status)

	_, err = db.ExecContext(ctx, auditQuery)
	if err != nil {
		return fmt.Errorf("audit write failed: %w", err)
	}

	log.Printf("Processed order %s for customer %s in region %s", event.OrderID, event.Customer, event.Region)
	return nil
}

// sanitizeRegion performs basic validation on region identifier
func sanitizeRegion(region string) string {
	// Only allow alphanumeric and underscore for table suffix
	var cleaned strings.Builder
	for _, r := range region {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_' {
			cleaned.WriteRune(r)
		}
	}
	result := cleaned.String()
	if result == "" {
		return "default"
	}
	return result
}

func main() {
	initDB()
	defer db.Close()

	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("KAFKA_GROUP_ID")

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers: brokers,
		Topic:   topic,
		GroupID: groupID,
	})
	defer reader.Close()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-sigChan
		cancel()
	}()

	log.Printf("Starting order stream processor on topic %s", topic)

	for {
		msg, err := reader.ReadMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				log.Println("Shutting down consumer")
				return
			}
			log.Printf("Error reading message: %v", err)
			continue
		}

		var event OrderEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			log.Printf("Failed to unmarshal event: %v", err)
			continue
		}

		if err := processOrderEvent(ctx, event); err != nil {
			log.Printf("Failed to process event: %v", err)
		}
	}
}
